CHOOSE = {"fr": "Choisis ta ville", "en": "Pick your city", "it": "Scegli la tua città", "de": "Wähle deine Stadt"}
CHOOSE_C = {"fr": "Choisis ton pays", "en": "Pick your country", "it": "Scegli il tuo paese", "de": "Wähle dein Land"}
FAQ_H = {"fr": "Questions fréquentes", "en": "Frequently asked questions", "it": "Domande frequenti", "de": "Häufige Fragen"}


def body(fam, lang, links_html):
    g = G[fam][lang]
    pick = (CHOOSE_C if fam == "esim" else CHOOSE)[lang]
    return (f'<p>{E(g["intro"])}</p><section><h2>{E(pick)}</h2><ul class="pv-other">{links_html}</ul></section>'
            + "".join(f"<section><h2>{E(h)}</h2><ul>" + "".join(f"<li>{E(x)}</li>" for x in xs) + "</ul></section>" for h, xs in g["secs"])
            + f'<section class="faq"><h2>{E(FAQ_H[lang])}</h2>' + "".join(f"<details><summary>{E(q)}</summary><p>{E(r)}</p></details>" for q, r in g["faq"]) + "</section>")


def ld(fam, lang):
    return '<script type="application/ld+json">' + json.dumps({
        "@context": "https://schema.org", "@type": "FAQPage",
        "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": r}} for q, r in G[fam][lang]["faq"]]},
        ensure_ascii=False) + "</script>"
